<script setup>
import {ref,reactive,onMounted,onBeforeUnmount} from 'vue'
import L from 'leaflet'
const mapEl=ref(null),active=ref('navigation'),picking=ref(''),searching=ref(''),suggestions=ref([]),error=ref(''),result=ref(null),busy=ref(false),preference=ref('优先选择耗时短的路线'),mode=ref('walk'),panel=ref(true)
const endpoints=reactive({origin:{text:'',point:null},destination:{text:'',point:null}})
let map,roads,markers,routeLayer,observer,searchTimer,searchToken=0,runToken=0
async function api(path,body){const response=await fetch('/api/navigation'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:undefined);const data=await response.json();if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'请求失败，请检查输入');return data}
function invalidate(){runToken++;result.value=null;routeLayer?.clearLayers();error.value=''}
function drawMarkers(){markers?.clearLayers();for(const [key,entry] of Object.entries(endpoints)){if(!entry.point)continue;const el=document.createElement('span');el.textContent=(key==='origin'?'起点：':'终点：')+entry.text;L.circleMarker([entry.point.latitude,entry.point.longitude],{radius:9,color:'white',weight:3,fillColor:key==='origin'?'#1a73e8':'#e94235',fillOpacity:1}).bindTooltip(el,{permanent:true,direction:'top'}).addTo(markers)}}
function choose(key,item){endpoints[key]={text:item.name,point:{latitude:item.latitude,longitude:item.longitude}};searching.value='';suggestions.value=[];picking.value='';invalidate();drawMarkers();map.panTo([item.latitude,item.longitude])}
function search(key){invalidate();endpoints[key].point=null;drawMarkers();searching.value=key;const token=++searchToken;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{try{const data=await api('/places?q='+encodeURIComponent(endpoints[key].text));if(token===searchToken)suggestions.value=data.items}catch(e){if(token===searchToken)error.value=e.message}},200)}
function swap(){[endpoints.origin,endpoints.destination]=[endpoints.destination,endpoints.origin];invalidate();drawMarkers()}
function selectOnMap(key){searching.value='';picking.value=key;panel.value=true;error.value=''}
function renderRoute(data){result.value=data;routeLayer.clearLayers();L.geoJSON(data.geojson,{style:{color:'#1a43c4',weight:7,opacity:.95},pointToLayer:(f,ll)=>L.circleMarker(ll,{radius:8})}).addTo(routeLayer);const bounds=routeLayer.getBounds();if(bounds.isValid())map.fitBounds(bounds,{paddingTopLeft:[innerWidth>720&&panel.value?420:30,80],paddingBottomRight:[40,80],maxZoom:18})}
async function navigate(ai=false){if(!endpoints.origin.point||!endpoints.destination.point){error.value='请为起点和终点选择搜索结果，或使用地图选点';return}busy.value=true;invalidate();searching.value='';picking.value='';const token=runToken;try{const data=await api(ai?'/recommend':'/route',{origin:endpoints.origin.point,destination:endpoints.destination.point,mode:mode.value,...(ai?{preference:preference.value}:{})});if(token===runToken)renderRoute(data)}catch(e){if(token===runToken)error.value=e.message}finally{busy.value=false}}
function fitCampus(){if(roads?.getBounds().isValid())map.fitBounds(roads.getBounds(),{paddingTopLeft:[innerWidth>720?420:30,70],paddingBottomRight:[30,70]})}
onMounted(async()=>{map=L.map(mapEl.value,{zoomControl:false,center:[0,0],zoom:16});L.control.zoom({position:'bottomright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);markers=L.layerGroup().addTo(map);routeLayer=L.featureGroup().addTo(map);map.on('click',e=>{if(!picking.value||busy.value)return;choose(picking.value,{name:`地图选点 ${e.latlng.lat.toFixed(5)}, ${e.latlng.lng.toFixed(5)}`,latitude:e.latlng.lat,longitude:e.latlng.lng})});observer=new ResizeObserver(()=>map.invalidateSize());observer.observe(mapEl.value);try{const data=await api('/map');const named=new Set();roads=L.geoJSON(data,{style:f=>({color:f.properties.highway==='cycleway'?'#22a447':['footway','pedestrian','steps'].includes(f.properties.highway)?'#66CCFF':'#f6c344',weight:4,opacity:.95}),onEachFeature(f,l){if(f.properties.name){const span=document.createElement('span');span.textContent=f.properties.name;l.bindTooltip(span,{permanent:!named.has(f.properties.name),direction:'center',className:'campus-road-name'});named.add(f.properties.name)}}}).addTo(map);fitCampus()}catch(e){error.value=e.message}})
onBeforeUnmount(()=>{clearTimeout(searchTimer);searchToken++;runToken++;observer?.disconnect();map?.remove()})
</script>
<template>
 <main class="navigation-app">
  <div ref="mapEl" class="navigation-map" aria-label="校园导航地图"></div>
  <div class="nav-brand"><b>CampusFlow</b><span>渭水校区</span><a href="/debug" target="_blank" rel="noopener">调试与标注 ↗</a></div>
  <div class="nav-tools"><button :class="{active:active==='navigation'}" @click="active='navigation';panel=true">↗ 导航</button><button :class="{active:active==='ai'}" @click="active='ai';panel=true">✦ AI 推荐</button><button @click="panel=!panel">{{panel?'收起':'展开'}}</button></div>
  <aside v-show="panel" class="navigation-panel" aria-label="导航查询">
   <h1>{{active==='ai'?'AI 出行推荐':'路线规划'}}</h1><p class="subtitle">搜索宿舍、教学楼，或直接在地图选点</p>
   <div v-for="key in ['origin','destination']" :key="key" class="endpoint">
    <label :for="key">{{key==='origin'?'起点':'终点'}}</label><div class="entry"><input :id="key" v-model="endpoints[key].text" :disabled="busy" :placeholder="key==='origin'?'搜索出发地点':'搜索要去的地点'" autocomplete="off" @input="search(key)" @focus="searching=key"><button :disabled="busy" :class="{picking:picking===key}" @click="selectOnMap(key)">地图选点</button></div>
    <ul v-if="searching===key&&suggestions.length" class="suggestions"><li v-for="p in suggestions" :key="p.id"><button @click="choose(key,p)"><b>{{p.name}}</b><small>{{p.location_type==='building_center'?'建筑中心，入口待确认':'地点'}} · {{p.longitude.toFixed(5)}}, {{p.latitude.toFixed(5)}}</small></button></li></ul>
    <small v-if="searching===key&&endpoints[key].text&&!suggestions.length">没有匹配结果时可地图选点；请输入更短的名称或楼号。</small>
   </div>
   <div class="mode-row"><button :disabled="busy" @click="swap">⇅ 交换</button><button :disabled="busy" :class="{active:mode==='walk'}" @click="mode='walk';invalidate()">步行</button><button :disabled="busy" :class="{active:mode==='bike'}" @click="mode='bike';invalidate()">骑行</button></div>
   <p v-if="picking" class="tip">点击地图设置{{picking==='origin'?'起点':'终点'}}</p>
   <template v-if="active==='ai'"><label for="ai-pref">出行偏好</label><textarea id="ai-pref" v-model="preference" maxlength="500" :disabled="busy" placeholder="例如：想快一点到，步行和骑行都可以"></textarea><p class="subtitle">AI 从计算出的步行、骑行方案中选择。点击后调用百炼，可能产生少量费用。</p><button class="primary" :disabled="busy||!preference.trim()" @click="navigate(true)">{{busy?'正在推荐…':'让 AI 推荐路线'}}</button></template>
   <button v-else class="primary" :disabled="busy" @click="navigate(false)">{{busy?'正在计算…':'显示路线'}}</button>
   <p v-if="error" class="error" role="alert">{{error}}</p>
   <section v-if="result" class="route-result" aria-label="路线结果"><div><strong>{{result.duration_minutes}} 分钟</strong><span>{{result.mode==='walk'?'步行':'骑行'}} · {{result.distance_m>=1000?(result.distance_m/1000).toFixed(2)+' 公里':result.distance_m+' 米'}}</span></div><p v-if="result.ai">✦ {{result.ai.reason}}</p><small v-if="result.ai">模型：{{result.ai.model}} · 推荐不代表实时路况</small><p>{{result.notice}}</p><p>起点距道路 {{result.origin_access_distance_m}} 米 · 终点距道路 {{result.destination_access_distance_m}} 米</p><button v-for="r in result.alternatives||[]" :key="r.id" @click="renderRoute(r)">备选：{{r.mode==='walk'?'步行':'骑行'}} {{r.duration_minutes}} 分钟</button></section>
   <p class="subtitle bottom-note">预计时间按步行4.5km/h、骑行12km/h计算。公交、实时拥堵和无障碍条件尚未接入。</p>
  </aside>
  <button class="campus-fit" @click="fitCampus">查看全校</button>
  <div class="road-legend"><span><i style="background:#f6c344"></i>道路／路径</span><span><i style="background:#22a447"></i>自行车道</span><span><i style="background:#66CCFF"></i>步行道</span></div>
 </main>
</template>
<style scoped>
.navigation-app{position:relative;height:100dvh;min-height:500px;color:#202124}.navigation-map{position:absolute;inset:0;background:#e9eee8}.nav-brand{position:absolute;top:18px;right:22px;z-index:700;display:flex;gap:12px;align-items:center;background:white;border-radius:20px;padding:10px 16px;box-shadow:0 2px 12px #0002}.nav-brand b{color:#1a73e8}.nav-brand a{font-size:11px;color:#64748b}.nav-tools{position:absolute;left:20px;top:20px;z-index:800;display:flex;gap:8px}.navigation-app button{background:white;border:1px solid #dadce0;border-radius:22px;padding:10px 16px}.nav-tools button{box-shadow:0 2px 7px #0002}.navigation-app button.active{background:#e8f0fe;color:#1967d2;border-color:#aecbfa}.navigation-panel{position:absolute;top:78px;left:20px;bottom:45px;width:370px;overflow:auto;z-index:750;background:white;border-radius:18px;box-shadow:0 3px 16px #0003;padding:24px}.navigation-panel h1{font-size:23px;margin:0 0 8px}.subtitle{font-size:12px;color:#667085;line-height:1.7}.endpoint{margin-top:18px}.endpoint label{font-weight:600;font-size:12px}.entry{display:flex;gap:6px;align-items:center;margin-top:6px}.entry input{width:100%;min-width:0;border:1px solid #dadce0;border-radius:8px;padding:12px}.entry button{flex-shrink:0;font-size:11px;border-radius:8px;padding:11px 9px}.entry button.picking{background:#e8f0fe;color:#1967d2}.mode-row{display:flex;gap:8px;margin:18px 0}.mode-row button{font-size:12px;flex:1}.navigation-panel .primary{width:100%;background:#1a73e8;color:white;border:0;border-radius:9px;font-weight:600;margin-top:12px;padding:14px}.suggestions{list-style:none;padding:0;margin:7px 0;background:#f8fafc;max-height:240px;overflow:auto;border-radius:8px}.suggestions li button{display:flex;flex-direction:column;text-align:left;gap:3px;width:100%;border:0;border-radius:0;padding:12px}.suggestions small,.endpoint small{color:#64748b;font-size:11px}.tip{color:#1967d2;padding:10px;background:#e8f0fe;border-radius:8px}.error{color:#b91c1c;background:#fef2f2;padding:12px;margin-top:12px;border-radius:8px}textarea{width:100%;min-height:90px;resize:vertical;padding:12px;border:1px solid #dadce0;border-radius:8px;margin:8px 0}.route-result{margin-top:20px;padding-top:18px;border-top:1px solid #eee}.route-result strong{font-size:27px;color:#188038;display:block}.route-result span{display:block;margin:5px 0 15px}.route-result p,.route-result small{font-size:12px;color:#64748b;line-height:1.7;margin:8px 0}.bottom-note{margin-top:18px}.campus-fit{position:absolute;bottom:85px;right:12px;z-index:700}.road-legend{position:absolute;bottom:24px;left:50%;transform:translateX(-20%);display:flex;gap:14px;background:white;padding:10px 14px;z-index:700;border-radius:18px;font-size:11px;box-shadow:0 2px 8px #0002}.road-legend span{white-space:nowrap}.road-legend i{width:18px;height:4px;display:inline-block;vertical-align:middle;margin-right:5px}:global(.campus-road-name){background:#fff9dd;border:0;box-shadow:none;font-size:11px;font-weight:600;color:#5d4e14;padding:2px 5px}@media(max-width:720px){.nav-brand{top:10px;right:10px;font-size:11px}.nav-brand a{display:none}.nav-tools{top:55px;left:10px}.navigation-panel{top:auto;bottom:14px;left:10px;right:10px;width:auto;max-height:48vh;padding:18px}.road-legend{top:110px;left:10px;bottom:auto;transform:none;gap:8px}.campus-fit{bottom:calc(48vh + 38px)}.navigation-app{min-height:600px}}
</style>
